// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testRegression_property() public {
        address nonLogger = address(this);
        bool result = c.logRedemptionRequested(
            address(0),
            bytes32(0),
            0,
            "",
            0,
            ""
        );
        assertTrue(result == false, "Non-approved logger should return false");
    }
}
